style.css:
@font-face {
  font-family: "Mykayla";
  src: url(data:font/woff;base64,) format("woff");
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

/* Apply the font — edit the selectors as needed */
body, 
p, 
div, 
span,
h1, h2, h3, h4, h5, h6,
input, textarea, button,
* {
  font-family: "Mykayla", sans-serif !important;
}
